":"manufacturer_entity","marketed_brand_overrides":{"FIAT":"Fiat"},"match_type":"diacritic_insensitive_prefix","source_field":"manufacturer","source_term":"FCA ITALY"},"MFE-FDFA3462B43EBB":{"base_behavior":"use_entity","canonical_name":"AMC","change_note":"Reviewed against the complete 52-case Borealis evidence export.","entity_role":"vehicle_manufacturer","kind":"manufacturer_entity","source_field":"brand","source_term":"AMC AMBASSADOR"},"MFE-FE2DD209A0DAB2":{"aliases":["AUTOMOBILE DACIA SA"],"base_behavior":"use_entity","canonical_name":"Dacia","change_note":"Extended approved Dacia legal-manufacturer punctuation variants","entity_id":"MFE-FE2DD209A0DAB2","entity_role":"vehicle_manufacturer","kind":"manufacturer_entity","match_type":"diacritic_insensitive_prefix","source_field":"manufacturer","source_term":"AUTOMOBILE DACIA S.A."},"MFE-JAGUAR-LAND-ROVER":{"base_behavior":"require_evidence_review","canonical_name":"Jaguar Land Rover","change_note":"Brand-confirmed child mapping tolerant of TS-concatenated legal-name addresses","entity_id":"MFE-JAGUAR-LAND-ROVER","entity_role":"corporate_group","kind":"manufacturer_entity","marketed_brand_overrides":{"JAGUAR":"Jaguar","LAND ROVER":"Land Rover"},"match_type":"approved_compact_prefix","source_field":"manufacturer","source_term":"JAGUAR LAND ROVER LIMITED"},"MFE-MAGYAR-SUZUKI":{"base_behavior":"use_entity","canonical_name":"Suzuki","change_note":"Approved Suzuki legal manufacturer prefix from matching Brand and model evidence","entity_id":"MFE-MAGYAR-SUZUKI","entity_role":"vehicle_manufacturer","kind":"manufacturer_entity","match_type":"diacritic_insensitive_prefix","source_field":"manufacturer","source_term":"MAGYAR SUZUKI CORPORATION"},"MFE-NIO-CO-LTD":{"base_behavior":"use_entity","canonical_name":"NIO","change_note":"Approved reviewed NIO legal-manufacturer prefix","entity_id":"MFE-NIO-CO-LTD","entity_role":"vehicle_manufacturer","kind":"manufacturer_entity","match_type":"diacritic_insensitive_prefix","reviewed_examples":["NIO CO.LTD"],"source_field":"manufacturer","source_term":"NIO CO.LTD"},"MFE-SAIC-MAXUS":{"base_behavior":"require_evidence_review","canonical_name":"SAIC Maxus","change_note":"Brand-confirmed Maxus child mapping for the reviewed SAIC Maxus legal manufacturer","entity_id":"MFE-SAIC-MAXUS","entity_role":"corporate_group","kind":"manufacturer_entity","marketed_brand_overrides":{"MAXUS":"Maxus"},"match_type":"diacritic_insensitive_prefix","source_field":"manufacturer","source_term":"SAIC MAXUS AUTOMOTIVE"},"MFE-ZHAOQING-XIAOPENG-BRAND":{"base_behavior":"require_evidence_review","canonical_name":"Zhaoqing Xiaopeng","change_note":"Brand-confirmed XPENG mapping for reviewed manufacturing entity","entity_id":"MFE-ZHAOQING-XIAOPENG-BRAND","entity_role":"corporate_group","kind":"manufacturer_entity","marketed_brand_overrides":{"XPENG":"XPENG"},"match_type":"diacritic_insensitive_prefix","reviewed_examples":["ZHAOQING XIAOPENG"],"source_field":"manufacturer","source_term":"ZHAOQING XIAOPENG"}}$northstar_delta$::jsonb;
    baseline_base text;
    baseline_overrides jsonb;
    current_latest text;
    existing_base text;
    existing_overrides jsonb;
    existing_note text;
    existing_activated_at timestamptz;
    expected_overrides jsonb;
BEGIN
    SELECT base_rule_version, overrides
    INTO baseline_base, baseline_overrides
    FROM core.translation_rule_versions
    WHERE version = baseline_version;

    IF baseline_overrides IS NULL THEN
        RAISE EXCEPTION 'Required baseline rule version % is missing', baseline_version;
    END IF;
    IF baseline_base <> expected_base_version THEN
        RAISE EXCEPTION 'Baseline catalog mismatch: expected %, found %',
            expected_base_version, baseline_base;
    END IF;

    expected_overrides := baseline_overrides || delta;

    SELECT base_rule_version, overrides, activation_note, activated_at
    INTO existing_base, existing_overrides, existing_note, existing_activated_at
    FROM core.translation_rule_versions
    WHERE version = target_version;

    IF existing_overrides IS NOT NULL THEN
        IF existing_base <> expected_base_version
           OR existing_overrides IS DISTINCT FROM expected_overrides
           OR existing_note IS DISTINCT FROM expected_activation_note
           OR existing_activated_at IS DISTINCT FROM expected_activated_at THEN
            RAISE EXCEPTION 'Target version % exists with conflicting content', target_version;
        END IF;
        RAISE NOTICE 'Target version % is already installed and verified', target_version;
        RETURN;
    END IF;

    SELECT version INTO current_latest
    FROM core.translation_rule_versions
    ORDER BY activated_at DESC, version DESC
    LIMIT 1;

    IF current_latest <> baseline_version THEN
        RAISE EXCEPTION 'Refusing activation: expected latest version %, found %',
            baseline_version, current_latest;
    END IF;

    INSERT INTO core.translation_rule_versions (
        version,
        base_rule_version,
        overrides,
        activation_note,
        activated_at
    ) VALUES (
        target_version,
        expected_base_version,
        expected_overrides,
        expected_activation_note,
        expected_activated_at
    );
END
$northstar_rules$;

COMMIT;

WITH baseline AS (
    SELECT overrides
    FROM core.translation_rule_versions
    WHERE version = 'ts-review-20260806T133621914615Z'
), target AS (
    SELECT version, base_rule_version, overrides, activation_note, activated_at
    FROM core.translation_rule_versions
    WHERE version = 'ts-review-20260807T112656115381Z'
)
SELECT
    target.version,
    target.base_rule_version,
    (SELECT count(*) FROM jsonb_object_keys(target.overrides)) AS total_overrides,
    count(changed.key) AS exported_delta_definitions,
    target.activated_at
FROM target
CROSS JOIN baseline
CROSS JOIN LATERAL jsonb_each(target.overrides) AS changed
WHERE baseline.overrides->changed.key IS DISTINCT FROM changed.value
GROUP BY target.version, target.base_rule_version, target.overrides,
         target.activation_note, target.activated_at;
